import sys
from collections import deque

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print("NO")
        return

    n = int(data[0])

    if n == 0:
        print("NO")
        return

    if n == 1:
        if len(data) == 1:
            print("YES")
        else:
            print("YES")
        return

    if len(data) < 2 * (n - 1) + 1:
        print("NO")
        return

    edges = data[1:]

    if len(edges) != 2 * (n - 1):
        print("NO")
        return

    node_set = set()

    parent_count = {}
    children = {}

    for i in range(n - 1):
        parent = int(edges[2 * i])
        child = int(edges[2 * i + 1])

        node_set.add(parent)
        node_set.add(child)

        if child in parent_count:
            print("NO")
            return

        parent_count[child] = parent

        if parent not in children:
            children[parent] = []
        children[parent].append(child)

    roots = [node for node in node_set if node not in parent_count]

    if len(roots) != 1:
        print("NO")
        return

    root = roots[0]

    for node in children:
        if len(children[node]) > 2:
            print("NO")
            return

    visited = set()
    queue = deque([root])

    while queue:
        node = queue.popleft()
        if node in visited:
            print("NO")
            return
        visited.add(node)

        if node in children:
            for child in children[node]:
                queue.append(child)

    if len(visited) != n:
        print("NO")
        return

    print("YES")

if __name__ == "__main__":
    main()
